 var p=SportsUIAuthoring.Page("Title",view.transform,"TRUCK SPORTS","Small trucks. Big games. • Local play");view.pages[0]=p;p.transform.Find("Title").GetComponent<TMPro.TMP_Text>().fontSizeMax=66;SportsUIAuthoring.Button(p.transform,"PLAY","play",new Vector2(0,165));SportsUIAuthoring.Button(p.transform,"HOW TO PLAY","help",new Vector2(0,65));SportsUIAuthoring.Button(p.transform,"SETTINGS","settings",new Vector2(0,-35));SportsUIAuthoring.Button(p.transform,"QUIT","quit",new Vector2(0,-135));SportsUIAuthoring.Text("Collection",p.transform,"BILLIARDS  •  HOCKEY\nOne collection. Two ways to drive.",new Vector2(1100,110),new Vector2(0,-280),28);
