 p=SportsUIAuthoring.Page("How to Play",view.transform,"HOW TO PLAY");view.pages[2]=p;SportsUIAuthoring.Text("Guidance",p.transform,"BILLIARDS\nDrive into the white cue with your front bumper once per shot. Clear your group, then the 8. Only a scratch permits competitive cue placement. Choose Practice for free setup. Hot seat passes the device between turns.\n\nHOCKEY\nAll six trucks drive and hit the puck continuously. A full crossing through either goal mouth scores for the attacking team. Own goals count. Regulation ties enter sudden-death overtime.\n\nKEYBOARD / CONTROLLER\nHockey: six keyboard clusters or whole / shared controllers. Opposite throttle brakes then reverses. Pause recovers one slot. Billiards retains its own controls. Esc / Start pauses.\n\nMenus: mouse, arrows / D-pad / stick, Enter / South submit, East / Esc back. Default names require no typing. Each sport has complete controls in its pause menu.",new Vector2(1260,570),new Vector2(0,-15),28);SportsUIAuthoring.Button(p.transform,"BACK","back",new Vector2(0,-385));SportsUIAuthoring.SettingsPage(view,3);foreach(var page in view.pages)page.SetActive(false);view.pages[0].SetActive(true);SportsBrandAuthoring.InstallTitle(view);EditorSceneManager.SaveScene(scene,FrontScene);AssetDatabase.SaveAssets();SportsUpdateAuthoring.UpgradeFront();SportsParticipantAuthoring.InstallFront();Debug.Log("TS_FRONT_AUTHORED");}
