 public static void Validate(){var horn=AssetDatabase.LoadAssetAtPath<SportsHornAssets>(SportsHornAuthoring.Path);if(horn==null||horn.defaultHorn==null)throw new Exception("Shared Sports horn audio is missing; run the explicit Sports horn asset authoring utility.");BilliardsBuilder.ValidateSavedScene();HockeyRuleFixtures.Run();HockeyParticipantFixtures.Run();BilliardsRuleFixtures.Run();BilliardsFeatureFixtures.Run();foreach(var path in new[]{FrontScene,HockeyAuthoring.Scene}){var scene=EditorSceneManager.OpenScene(path);foreach(var root in scene.GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0)throw new Exception("Missing script in "+path+": "+t.name);if(UnityEngine.Object.FindObjectsByType<UnityEngine.EventSystems.EventSystem>(FindObjectsInactive.Include).Length!=1||UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("Scene event/listener count invalid: "+path);if(path==HockeyAuthoring.Scene){var m=UnityEngine.Object.FindAnyObjectByType<HockeyMatch>();if(m==null||m.trucks.Length!=6||m.players.Length!=6||m.agents.Length!=6||m.labels.Length!=6||m.menus.names.Length!=6||m.puck==null||m.menus==null||m.feedback.clips.Length!=7||m.feedback.clips.Any(c=>c==null)||m.truckGoalBarriers.Length!=2)throw new Exception("Hockey scene references incomplete");if(m.puck.GetComponent<Collider>().sharedMaterial.bounciness<.69f||AssetDatabase.LoadAssetAtPath<PhysicsMaterial>("Assets/TruckHockey/Materials/Board bounce.asset").bounciness<.77f)throw new Exception("Saved hockey restitution invalid");if(m.trucks.Any(t=>t.GetComponentsInChildren<Collider>().Count(c=>c.attachedRigidbody==t.body)!=1))throw new Exception("Unexpected truck collider model");}Debug.Log("TS_SAVED_SCENE_VALIDATED "+path);}LWS.TruckBowling.Editor.BowlingAuthoring.Validate();LWS.TruckAirHockey.Editor.AirHockeyAuthoring.Validate();LWS.TruckWallball.Editor.WallballAuthoring.Validate();LWS.TruckCornhole.Editor.CornholeAuthoring.Validate();LWS.TruckCheeseRolling.Editor.CheeseAuthoring.Validate();LWS.TruckDockDiving.Editor.DockAuthoring.Validate();LWS.TruckKeepaway.Editor.KeepawayAuthoring.Validate();LWS.TruckCurling.Editor.CurlingAuthoring.Validate();LWS.TruckBaseJumping.Editor.BaseJumpAuthoring.Validate();LWS.TruckKeepaway.Editor.KeepawayChaosAuthoring.Validate();LWS.TruckKeepaway.Editor.KeepawayBoundaryAuthoring.Validate();LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Validate();LWS.TruckTerrierRacing.Editor.TerrierAuthoring.Validate();LWS.TruckMinefield.Editor.MinefieldAuthoring.Validate();LWS.TruckMattressRacing.Editor.MattressAuthoring.Validate();LWS.TruckWifeCarrying.Editor.WifeAuthoring.Validate();LWS.TruckMusicalParking.Editor.ParkingAuthoring.Validate();LWS.TruckGiantSwing.Editor.SwingAuthoring.Validate();LWS.TruckBuzkashi.Editor.BuzAuthoring.Validate();LWS.TruckBogSnorkelling.Editor.BogAuthoring.Validate();LWS.TruckBungeeDemolition.Editor.BungeeAuthoring.Validate();LWS.TruckFishing.Editor.FishingAuthoring.Validate();LWS.TruckSumo.Editor.SumoAuthoring.Validate();LWS.TruckTargetLaunch.Editor.TargetAuthoring.Validate();LWS.TruckTargetLaunch.Editor.TargetFixtures.Run();LWS.TruckFieldGoal.Editor.FieldGoalAuthoring.Validate();LWS.TruckFieldGoal.Editor.FieldGoalFixtures.Run();LWS.TruckBeerPong.Editor.PongAuthoring.Validate();PongFixtures.Main();LWS.TruckPoker.Editor.PokerAuthoring.Validate();LWS.TruckTugOfWar.Editor.TugAuthoring.Validate();LWS.TruckSkeeBall.Editor.SkeeAuthoring.Validate();LWS.TruckLogRolling.Editor.LogAuthoring.Validate();LWS.TruckDodgeball.Editor.DodgeAuthoring.Validate();LWS.TruckDerby.Editor.DerbyAuthoring.Validate();LWS.TruckPedestrianPlowing.Editor.PlowAuthoring.Validate();LWS.TruckPedestrianPlowing.Editor.PlowCabAuthoring.Validate();LWS.TruckPedestrianPlowing.Editor.PlowFixtures.Run();ValidateNewScene(LWS.TruckKickball.Editor.KickballAuthoring.Scene,LWS.TruckKickball.Editor.Kickba