 // New-sport validators inspect the active scene. Always bind the correct
 // saved scene first; an unrelated preceding validator must not supply it.
 static void ValidateNewScene(string path,Action validate){
  var scene=EditorSceneManager.OpenScene(path);
  foreach(var root in scene.GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0)throw new Exception("Missing script in "+path+": "+t.name);
  if(UnityEngine.Object.FindObjectsByType<UnityEngine.EventSystems.EventSystem>(FindObjectsInactive.Include).Length!=1||UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("Scene event/listener count invalid: "+path);
  validate();Debug.Log("TS_SAVED_SCENE_VALIDATED "+path);
 }
 static void WithSportsTitle(Action build){string playerPath="ProjectSettings/ProjectSettings.asset",scenePath="ProjectSettings/EditorBuildSettings.asset";byte[] oldPlayer=File.ReadAllBytes(playerPath),oldScene=File.ReadAllBytes(scenePath);string name=PlayerSettings.productName,company=PlayerSettings.companyName;Directory.CreateDirectory("Logs/TruckSports");File.WriteAllBytes("Logs/TruckSports/host-player-settings.backup",oldPlayer);File.WriteAllBytes("Logs/TruckSports/host-build-settings.backup",oldScene);
 try{PlayerSettings.productName="Truck Sports";if(Array.IndexOf(Environment.GetCommandLineArgs(),"-tsValidationPrefs")>=0)PlayerSettings.companyName="LWS Truck Sports Validation";build();}
 finally{PlayerSettings.productName=name;PlayerSettings.companyName=company;AssetDatabase.SaveAssets();AssetDatabase.ReleaseCachedFileHandles();RestoreExact(playerPath,oldPlayer);if(!File.ReadAllBytes(scenePath).SequenceEqual(oldScene))RestoreExact(scenePath,oldScene);if(!File.ReadAllBytes(playerPath).SequenceEqual(oldPlayer)||!File.ReadAllBytes(scenePath).SequenceEqual(oldScene))throw new Exception("Scoped build settings restoration failed");Debug.Log("TS_HOST_SETTINGS_RESTORED");}}
 static string BuildOutput(){var args=Environment.GetCommandLineArgs();int index=Array.IndexOf(args,"-tsBuildOutput");if(index<0)return "Builds/TruckSports/TruckSports.exe";if(index+1>=args.Length)throw new ArgumentException("Missing validation build output");string output=Path.GetFullPath(args[index+1]),root=Path.GetFullPath("Builds")+Path.DirectorySeparatorChar;if(!output.StartsWith(root,StringComparison.OrdinalIgnoreCase)||Path.GetFileName(output)!="TruckSports.exe")throw new ArgumentException("Sports output must be TruckSports.exe inside this project's Builds directory");return output;}
 static void RestoreExact(string path,byte[] bytes){if(File.ReadAllBytes(path).SequenceEqual(bytes))return;using(var stream=new FileStream(path,FileMode.Open,FileAccess.Write,FileShare.ReadWrite|FileShare.Delete)){stream.Position=0;stream.Write(bytes,0,bytes.Length);if(stream.Length!=bytes.Length)stream.SetLength(bytes.Length);stream.Flush();}if(!File.ReadAllBytes(path).SequenceEqual(bytes))throw new IOException("Exact restoration failed: "+path);}
 public static void VerifyFailureRestoration(){string oldName=PlayerSettings.productName;byte[] before=File.ReadAllBytes("ProjectSettings/ProjectSettings.asset"),scene=File.ReadAllBytes("ProjectSettings/EditorBuildSettings.asset");bool caught=false;string failure=null;try{WithSportsTitle(()=>{if(PlayerSettings.productName!="Truck Sports")throw new Exception("Scoped title not applied");throw new IOException("Truck Sports deliberate restoration fixture");});}catch(IOException e){failure=e.Message;caught=e.Message=="Truck Sports deliberate restoration fixture";}if(!caught||PlayerSettings.productName!=oldName||!File.ReadAllBytes("ProjectSettings/ProjectSettings.asset").SequenceEqual(before)||!File.ReadAllBytes("ProjectSettings/EditorBuildSettings.asset").SequenceEqual(scene))throw new Exception("Build failure restoration fixture failed: caught="+caught+" oldName="+oldName+" currentName="+PlayerSettings.productName+" playerBytes="+File.ReadAllBytes("ProjectSettings/ProjectSettings.asset").SequenceEqual(before)+" sceneBytes="+File.ReadAllBytes("ProjectSettings/EditorBuildSettings.asset").SequenceEqual(scene)+" IOException="+failure);Debug.Log("TS_FAILURE_RESTORATION_PASS");}
