 public static void Build(){Validate();BuildFocused();}
 public static void BuildFocused(){foreach(var scene in SceneList())if(!File.Exists(scene))throw new FileNotFoundException("Required saved Sports scene missing",scene);VerifyFailureRestoration();string output=BuildOutput();Directory.CreateDirectory(Path.GetDirectoryName(output));Directory.CreateDirectory("Logs/TruckSports");WithSportsTitle(()=>{var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=SceneList(),target=BuildTarget.StandaloneWindows64,locationPathName=output,options=BuildOptions.Development});File.WriteAllText("Logs/TruckSports/build-summary.txt",report.summary.result+"\nErrors: "+report.summary.totalErrors+"\nWarnings: "+report.summary.totalWarnings+"\nBytes: "+report.summary.totalSize+"\nDuration: "+report.summary.totalTime+"\nStartup: "+FrontScene+"\nScenes: "+string.Join(", ",SceneList()));if(report.summary.result!=UnityEditor.Build.Reporting.BuildResult.Succeeded||report.summary.totalErrors>0)throw new Exception("Truck Sports build failed: "+report.summary.result+" errors="+report.summary.totalErrors);Debug.Log("TS_BUILD_SUCCEEDED "+Path.GetFullPath(output));});}
